import {
  BadRequestException,
  Injectable,
  Logger,
  NotFoundException,
  PayloadTooLargeException,
  ServiceUnavailableException,
} from '@nestjs/common';
import { createHmac, randomBytes, timingSafeEqual } from 'crypto';
import { createWriteStream, promises as fs } from 'fs';
import * as path from 'path';
import { Readable, Transform } from 'stream';
import { pipeline } from 'stream/promises';
import { ALLOWED_FILE_TYPES, MAX_FILE_BYTES } from './review.types';

/** Ids that may appear in file paths: generated by us, never containing separators */
const SAFE_ID = /^[A-Za-z0-9_-]{1,100}$/;
export const SIGNED_URL_TTL_SECONDS = 10 * 60;

export function isSafeId(id: string): boolean {
  return typeof id === 'string' && SAFE_ID.test(id);
}

/** Where review files live: `REVIEW_UPLOAD_DIR`, default `uploads/reviews` */
export function reviewUploadRoot(): string {
  return path.resolve(process.env.REVIEW_UPLOAD_DIR || path.join('uploads', 'reviews'));
}

/** Staging directory for multipart uploads before they're moved into a review */
export function reviewIncomingDir(): string {
  return path.join(reviewUploadRoot(), '.incoming');
}

export function newId(prefix: string): string {
  return `${prefix}_${randomBytes(12).toString('hex')}`;
}

/**
 * Review files on local disk (`REVIEW_UPLOAD_DIR`, default `uploads/reviews`,
 * one directory per review) and the HMAC-signed URLs they're served from.
 */
@Injectable()
export class ReviewFilesService {
  private readonly logger = new Logger(ReviewFilesService.name);
  readonly root: string;
  private readonly secret: Buffer | null;

  constructor() {
    this.root = reviewUploadRoot();
    const configured = process.env.REVIEW_FILE_SECRET;
    const env = process.env.NODE_ENV;
    if (configured) {
      this.secret = Buffer.from(configured, 'utf8');
    } else if (env === 'development' || env === 'test') {
      this.logger.warn(
        'REVIEW_FILE_SECRET is not set; using a random secret for this process. Signed review file URLs stop working on restart.',
      );
      this.secret = randomBytes(32);
    } else {
      this.logger.error('REVIEW_FILE_SECRET is not set; review files will not be served until it is.');
      this.secret = null;
    }
  }

  /** Staging directory for multipart uploads before they're moved into a review */
  get incomingDir(): string {
    return path.join(this.root, '.incoming');
  }

  reviewDir(reviewId: string): string {
    if (!isSafeId(reviewId)) throw new BadRequestException('Invalid review id');
    return path.join(this.root, reviewId);
  }

  filePath(reviewId: string, storageId: string): string {
    if (!isSafeId(storageId)) throw new BadRequestException('Invalid file id');
    return path.join(this.reviewDir(reviewId), storageId);
  }

  /** Public file id used in signed URLs: `<reviewId>.<storageId>` */
  static fileId(reviewId: string, storageId: string): string {
    return `${reviewId}.${storageId}`;
  }

  static parseFileId(fileId: string): { reviewId: string; storageId: string } | null {
    const parts = typeof fileId === 'string' ? fileId.split('.') : [];
    if (parts.length !== 2 || !isSafeId(parts[0]) || !isSafeId(parts[1])) return null;
    return { reviewId: parts[0], storageId: parts[1] };
  }

  /**
   * Streams a request body to a new file in the review's directory, enforcing
   * the 50MB cap while streaming. Returns the stored name and size.
   */
  async writeStream(reviewId: string, body: Readable, contentType: string): Promise<{ storageId: string; size: number }> {
    const dir = this.reviewDir(reviewId);
    await fs.mkdir(dir, { recursive: true });
    const storageId = newId('f');
    const target = path.join(dir, storageId);
    let size = 0;
    const limiter = new Transform({
      transform(chunk: Buffer, _enc, cb) {
        size += chunk.length;
        if (size > MAX_FILE_BYTES) cb(new PayloadTooLargeException('Files can be up to 50MB'));
        else cb(null, chunk);
      },
    });
    try {
      await pipeline(body, limiter, createWriteStream(target, { flags: 'wx' }));
      if (size === 0) throw new BadRequestException('The file is empty');
      await this.assertContentMatches(target, contentType);
    } catch (error) {
      await fs.rm(target, { force: true });
      throw error;
    }
    return { storageId, size };
  }

  /** Moves a staged multipart upload into the review's directory under a new random name */
  async adopt(reviewId: string, stagedPath: string, contentType: string): Promise<{ storageId: string }> {
    const staged = path.resolve(stagedPath);
    if (path.dirname(staged) !== this.incomingDir) throw new BadRequestException('Invalid upload');
    try {
      await this.assertContentMatches(staged, contentType);
      const dir = this.reviewDir(reviewId);
      await fs.mkdir(dir, { recursive: true });
      const storageId = newId('f');
      await fs.rename(staged, path.join(dir, storageId));
      return { storageId };
    } catch (error) {
      await fs.rm(staged, { force: true });
      throw error;
    }
  }

  /** Deletes a staged multipart upload that won't be kept */
  async discardStaged(stagedPath: string): Promise<void> {
    const staged = path.resolve(stagedPath);
    if (path.dirname(staged) === this.incomingDir) await fs.rm(staged, { force: true });
  }

  async removeFile(reviewId: string, storageId: string): Promise<void> {
    await fs.rm(this.filePath(reviewId, storageId), { force: true });
  }

  async removeReviewFiles(reviewId: string): Promise<void> {
    await fs.rm(this.reviewDir(reviewId), { recursive: true, force: true });
  }

  /** Rejects files whose bytes don't look like the declared type */
  async assertContentMatches(filePath: string, contentType: string): Promise<void> {
    const handle = await fs.open(filePath, 'r');
    const head = Buffer.alloc(4096);
    let read = 0;
    try {
      ({ bytesRead: read } = await handle.read(head, 0, head.length, 0));
    } finally {
      await handle.close();
    }
    if (!sniffMatches(head.subarray(0, read), contentType)) {
      throw new BadRequestException(`The file isn't a valid ${ALLOWED_FILE_TYPES[contentType] ?? 'file'}`);
    }
  }

  /** Builds a signed URL path for a stored file, valid for 10 minutes */
  signedPath(reviewId: string, storageId: string, now = Date.now()): string {
    const fileId = ReviewFilesService.fileId(reviewId, storageId);
    const expires = Math.floor(now / 1000) + SIGNED_URL_TTL_SECONDS;
    return `/api/v1/review-files/${fileId}?expires=${expires}&sig=${this.sign(fileId, expires)}`;
  }

  /** Whether a signature is valid and unexpired */
  verify(fileId: string, expires: string | number, sig: string, now = Date.now()): boolean {
    const exp = Number(expires);
    if (!Number.isInteger(exp) || exp * 1000 <= now || typeof sig !== 'string') return false;
    const expected = Buffer.from(this.sign(fileId, exp));
    const actual = Buffer.from(sig);
    return expected.length === actual.length && timingSafeEqual(expected, actual);
  }

  private sign(fileId: string, expires: number): string {
    if (!this.secret) {
      throw new ServiceUnavailableException('Review file serving is not configured (REVIEW_FILE_SECRET)');
    }
    return createHmac('sha256', this.secret).update(`${fileId}:${expires}`).digest('base64url');
  }

  async assertExists(filePath: string): Promise<void> {
    try {
      await fs.access(filePath);
    } catch {
      throw new NotFoundException('File not found');
    }
  }
}

function sniffMatches(head: Buffer, contentType: string): boolean {
  const starts = (bytes: number[], offset = 0) => bytes.every((b, i) => head[offset + i] === b);
  switch (contentType) {
    case 'application/pdf':
      return head.includes(Buffer.from('%PDF-'));
    case 'image/png':
      return starts([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
    case 'image/jpeg':
      return starts([0xff, 0xd8, 0xff]);
    case 'image/gif':
      return head.subarray(0, 6).toString('ascii') === 'GIF87a' || head.subarray(0, 6).toString('ascii') === 'GIF89a';
    case 'image/webp':
      return head.subarray(0, 4).toString('ascii') === 'RIFF' && head.subarray(8, 12).toString('ascii') === 'WEBP';
    case 'image/svg+xml':
      return /<svg[\s>]/i.test(head.toString('utf8'));
    default:
      return false;
  }
}

/** A filename safe to put in a Content-Disposition header */
export function contentDisposition(filename: string): string {
  const name = (filename || 'file').replace(/[\r\n"\\]/g, '').slice(0, 200) || 'file';
  const ascii = name.replace(/[^\x20-\x7e]/g, '_');
  return `inline; filename="${ascii}"; filename*=UTF-8''${encodeURIComponent(name)}`;
}
